import{_ as a,a0 as p,w as s,s as m,ao as r,I as l,x as e,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"一個Linux中用於監控的簡易shell腳本 | LCTT x X-CMD","titleTemplate":false,"description":"一個Linux中用於監控的簡易shell腳本 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一個Linux中用於監控的簡易shell腳本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一個Linux中用於監控的簡易shell腳本 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150512 A Shell Script to Monitor Network, Disk Usage, Uptime, Load Average and RAM Usage in Linux","title":"一個Linux中用於監控的簡易shell腳本","tag":"201506","desc":""},"relativePath":"201506/20150512 A Shell Script to Monitor Network, Disk Usage, Uptime, Load Average and RAM Usage in Linux.md","filePath":"[post].md"}'),d={name:"201506/20150512 A Shell Script to Monitor Network, Disk Usage, Uptime, Load Average and RAM Usage in Linux.md"};function u(h,t,x,w,L,T){const i=p("Link");return s(),m("div",null,[t[18]||(t[18]=r('<h1 id="一個linux中用於監控的簡易shell腳本" tabindex="-1">一個Linux中用於監控的簡易shell腳本 <a class="header-anchor" href="#一個linux中用於監控的簡易shell腳本" aria-label="Permalink to “一個Linux中用於監控的簡易shell腳本”">​</a></h1><p>系統管理員的任務真的很艱難，因為他/她必須監控服務器、用户、日誌，還得創建備份，等等等等。對於大多數重複性的任務，大多數管理員都會寫一個自動化腳本來日復一日地重複這些任務。這裏，我們已經寫了一個shell腳本給大家，用來自動化完成系統管理員所要完成的常規任務，這可能在多數情況下，尤其是對於新手而言十分有用，他們能通過該腳本獲取到大多數的他們想要的信息，包括系統、網絡、用户、負載、內存、主機、內部IP、外部IP、開機時間等。</p><p>我們已經注意並進行了格式化輸出（在一定程度上哦）。此腳本不包含任何惡意內容，並且它能以普通用户帳號運行。事實上，我們也推薦你以普通用户運行該腳本，而不是root。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Linux-Health-Monitoring.png" alt="Linux Server Health Monitoring"></p><p><em>監控Linux系統健康的Shell腳本</em></p><p>在保留Tecmint和腳本作者應得榮譽的前提下，可以自由使用/修改/再分發下面代碼。我們已經試着在一定程度上自定義了輸出結果，除了要求的輸出內容外，其它內容都不會生成。我們也已經試着使用了那些Linux系統中通常不使用的變量，這些變量應該是可以隨便用的。</p><h4 id="最小系統要求" tabindex="-1">最小系統要求 <a class="header-anchor" href="#最小系統要求" aria-label="Permalink to “最小系統要求”">​</a></h4><p>你所需要的一切，就是一台正常運轉的Linux機器。</p><h4 id="依賴性" tabindex="-1">依賴性 <a class="header-anchor" href="#依賴性" aria-label="Permalink to “依賴性”">​</a></h4><p>對於一個標準的Linux發行版，使用此軟件包不需任何依賴。此外，該腳本不需要root權限來執行。但是，如果你想要安裝，則必須輸入一次root密碼。</p><h4 id="安全性" tabindex="-1">安全性 <a class="header-anchor" href="#安全性" aria-label="Permalink to “安全性”">​</a></h4><p>我們也關注到了系統安全問題，所以在安裝此包時，不需要安裝任何額外包，也不需要root訪問權限來運行。此外，源代碼是採用Apache 2.0許可證發佈的，這意味着只要你保留Tecmint的版權，你可以自由地編輯、修改並再分發該代碼。</p><h3 id="如何安裝和運行腳本" tabindex="-1">如何安裝和運行腳本？ <a class="header-anchor" href="#如何安裝和運行腳本" aria-label="Permalink to “如何安裝和運行腳本？”">​</a></h3>',13)),l("p",null,[t[1]||(t[1]=e("首先，使用",-1)),n(i,{href:"http://www.tecmint.com/10-wget-command-examples-in-linux/"},{default:o(()=>[...t[0]||(t[0]=[e("wget命令",-1)])]),_:1}),t[2]||(t[2]=e("下載監控腳本",-1)),t[3]||(t[3]=l("code",null,"“tecmint_monitor.sh”",-1)),t[4]||(t[4]=e("，給它賦予合適的執行權限。",-1))]),t[19]||(t[19]=r(`<pre><code># wget http://tecmint.com/wp-content/scripts/tecmint_monitor.sh
# chmod 755 tecmint_monitor.sh
</code></pre><p>強烈建議你以普通用户身份安裝該腳本，而不是root。安裝過程中會詢問root密碼，並且在需要的時候安裝必要的組件。</p><p>要安裝“<code>tecmint_monitor.sh</code>”腳本，只需像下面這樣使用-i（安裝）選項就可以了。</p><pre><code>./tecmint_monitor.sh -i 
</code></pre><p>在提示你輸入root密碼時輸入該密碼。如果一切順利，你會看到像下面這樣的安裝成功信息。</p><pre><code>Password: 
Congratulations! Script Installed, now run monitor Command
</code></pre><p>安裝完畢後，你可以在任何位置，以任何用户調用命令<code>‘monitor’</code>來運行該腳本。如果你不喜歡安裝，你需要在每次運行時輸入路徑。</p><pre><code># ./Path/to/script/tecmint_monitor.sh
</code></pre><p>現在，以任何用户從任何地方運行monitor命令，就是這麼簡單：</p><pre><code>$ monitor
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/TecMint-Monitor-Script.gif" alt="TecMint Monitor Script in Action"></p><p>你運行命令就會獲得下面這些各種各樣和系統相關的信息：</p><ul><li>互聯網連通性</li><li>操作系統類型</li><li>操作系統名稱</li><li>操作系統版本</li><li>架構</li><li>內核版本</li><li>主機名</li><li>內部IP</li><li>外部IP</li><li>域名服務器</li><li>已登錄用户</li><li>內存使用率</li><li>交換分區使用率</li><li>磁盤使用率</li><li>平均負載</li><li>系統開機時間</li></ul><p>使用-v（版本）開關來檢查安裝的腳本的版本。</p><pre><code>$ monitor -v

tecmint_monitor version 0.1
Designed by Tecmint.com
Released Under Apache 2.0 License
</code></pre><h3 id="小結" tabindex="-1">小結 <a class="header-anchor" href="#小結" aria-label="Permalink to “小結”">​</a></h3><p>該腳本在一些機器上可以開機即用，這一點我已經檢查過。相信對於你而言，它也會正常工作。如果你們發現了什麼毛病，可以在評論中告訴我。這個腳本還不完善，這僅僅是個開始。從這裏開始，你可以將它改進到任何程度。如果你想要編輯腳本，將它帶入一個更深的層次，儘管隨意去做吧，別忘了給我們應的的榮譽，也別忘了把你更新後的腳本拿出來和我們分享哦，這樣，我們也會更新此文來給你應得的榮譽。</p><p>別忘了和我們分享你的想法或者腳本，我們會在這兒幫助你。謝謝你們給予的所有摯愛。繼續瀏覽，不要走開哦。</p><hr>`,19)),l("p",null,[t[6]||(t[6]=e("via: ",-1)),n(i,{href:"http://www.tecmint.com/linux-server-health-monitoring-script/"},{default:o(()=>[...t[5]||(t[5]=[e("http://www.tecmint.com/linux-server-health-monitoring-script/",-1)])]),_:1})]),l("p",null,[t[10]||(t[10]=e("作者：",-1)),n(i,{href:"http://www.tecmint.com/author/avishek/"},{default:o(()=>[...t[7]||(t[7]=[e("Avishek Kumar",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),n(i,{href:"https://github.com/GOLinux"},{default:o(()=>[...t[8]||(t[8]=[e("GOLinux",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[15]||(t[15]=e("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創翻譯，",-1)),n(i,{href:"https://linux.cn/"},{default:o(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const c=a(d,[["render",u]]);export{f as __pageData,c as default};
